"type": "thinking",
"thinking": "...",
"signature": "WaUjzkyp...",
},
{
"type":"text",
"text": "...",
"id": "msg_abc123",
},
],
response_metadata: { model_provider: "anthropic" },
});

console.log(message.contentBlocks);
```



